"""Bound actual T45 inspection and reused accepted primary-source passages."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 local=['curriculum/modules/T45.md',*[f'curriculum/projects/PR-T45-{i:02}.md' for i in range(1,11)],*[f'assessor/legacy_depth/PR-T45-{i:02}.md' for i in range(1,11)],*[f'fixtures/memory_lab/PR-T45-{i:02}.json' for i in range(1,11)],'labs/foundations/include/foundation.h','labs/foundations/src/foundation.c','assessor/foundations/foundation.c','labs/performance_followthrough/stack.c','research/performance_debugging/memory_resources.json']
 resources=[{'id':'R-MEM-FOLLOW-LOCAL','kind':'repository-inspection','paths':local,'sha256':{p:sha(ROOT/p) for p in local},'locators':['Complete T45 original tasks/expected results/variants,10project briefs/assessor notes/fixtures.','Module memory/object/stack/layout/lifetime/init/async contracts;retained foundation size/constructor/async implementations and stack specimen.'],'limits':['Historical receipts remain separate.','No fresh whole-book or whole-manual reading claim.']}]
 prior=ROOT/'research/performance_debugging/memory_resources.json'
 for r in json.loads(prior.read_text()):resources.append({'id':r['id'],'kind':'reused-inspected-authority','registry_path':prior.relative_to(ROOT).as_posix(),'registry_sha256':sha(prior),'locators':r['locators'],'prior_inspection':r.get('inspection'),'scope':'Previously accepted bounded passages reused for unchanged T45 contract;not fresh whole-source inspection.'})
 resources += [{'id':'R-MEM-FOLLOW-N3096-CKD','kind':'primary-working-draft','url':'https://www.open-std.org/jtc1/sc22/wg14/www/docs/n3096.pdf','edition':'N3096 April1,2023 working draft','accessed_utc':'2026-10-18','locators':['PDF index329,printed311:7.20/7.20.1 paragraphs1–6;macro operations,type restrictions,infinite-range arithmetic,result wrapping and overflow indication'],'limits':['This is not published ISO C23.','Actual installed GCC15/Clang21 headers are separately recorded by campaign.','Optional comparison does not change C17 baseline.']},{'id':'R-MEM-FOLLOW-AN4839','kind':'primary-manual','url':'https://www.st.com/resource/en/application_note/an4839-level-1-cache-on-stm32f7-series-and-stm32h7-series-stmicroelectronics.pdf','edition':'AN4839 Rev2 March6,2018','accessed_utc':'2026-10-18','locators':['3.2 PDFpp5–7:write-back CPU/DMA incoherency and clean/invalidate alternatives.','4 PDFp8:cache maintenance before DMA and before consuming received data.'],'limits':['Bounded cache-coherency authority only;the example is not a universal M7 bank/controller route.','Exact chosen part,bus path,MPU,stop/reset and physical observation must be independently qualified.']}]
 values={'resources':{'schema_version':1,'resources':resources},'source_access':{'schema_version':1,'status':'bounded-local-inspection-reused-authority-and-two-fresh-primary-passages','actual_local_reads':local,'gaps':['Exact published C17/C23 not obtained;N3096 remains explicitly a draft.','No physical board reset,DMA,cache,IRQ or stack measurement.','No independent delayed learner observation.']},'research_gate':{'schema_version':1,'state':'author-ready-for-exact-memory-followthrough','guard_required':'tools/check_memory_followthrough.py','independent_reviewer':'not-run','physical_observation':'not-run'}}
 for name,value in values.items():(HERE/(name+'.json')).write_text(json.dumps(value,indent=2)+'\n')
if __name__=='__main__':main()
